            project="TestProject",
            image="path/to/image.png",
            debug=False,
            color_alignment=False,
            alignment=False,
            object_alignment=False,
            apply_mask=False,
            symmetry=None,
            blur=False,
            aggregate=False,
            skip_color_analysis=True,
            skip_report_generation=True,
            load_state_from=None,
            save_state_to=None
        )

    @patch('src.pipeline.DatabaseManager')
    @patch('src.pipeline.SessionLocal')
    @patch('src.pipeline.ProjectManager')
    @patch('src.pipeline.load_image')
    @patch('src.pipeline.extract_metadata_from_filename')
    @patch('src.pipeline.ReportingPipeline')
    def test_pipeline_initialization_and_loading(self, mock_report_cls, mock_meta, mock_load_img, MockPM, MockSession, MockDB, mock_args):
        # Setup
        mock_pm = MockPM.return_value
        mock_pm.get_project_data.return_value = {"key": "value"}

        mock_load_img.return_value = (np.zeros((100,100,3)), None)
        mock_meta.return_value = {"part_number": "123"}

        # Init
        pipeline = Pipeline(mock_args)
        pipeline.load_project_data()

        assert pipeline.project_data == {"key": "value"}

        # Run process_image
        # We need to mock _archive_input_image or ensure db_manager works
        with patch.object(pipeline, '_archive_input_image'), \
             patch.object(pipeline, 'run_analysis_phase'), \
             patch.object(pipeline, '_finalize_analysis'):
            pipeline.process_image("path/to/image.png")

        mock_meta.assert_called_once()
        mock_load_img.assert_called_once()

    @patch('src.pipeline.DatabaseManager')
    @patch('src.pipeline.SessionLocal')
    @patch('src.pipeline.ProjectManager')
    @patch('src.pipeline.load_image')
    @patch('src.pipeline.extract_metadata_from_filename')
    @patch('src.pipeline.ReportingPipeline')
    def test_run_full_pipeline_orchestration(self, mock_report_cls, mock_meta, mock_load, MockPM, MockSession, MockDB, mock_args):
        # Test that sub-pipelines are called based on flags
        mock_args.color_alignment = True
        mock_args.skip_color_analysis = False

        mock_load.return_value = (np.zeros((100,100,3)), None)
        mock_meta.return_value = {"part_number": "123"}

        pipeline = Pipeline(mock_args)
        pipeline.project_manager.get_project_data.return_value = {
            "lower_hsv": np.array([0,0,0]), 
            "upper_hsv": np.array([10,10,10]), 
            "center_hsv": np.array([5,5,5]),
            "dataset_debug_info": []
        }
        pipeline.project_manager.get_project_file_paths.return_value = {}

        # Mock sub-pipelines
        with patch.object(pipeline, '_do_color_correction') as mock_cc, \
             patch.object(pipeline, '_do_color_analysis') as mock_ca, \
             patch.object(pipeline, '_initialize_db_session'), \
             patch.object(pipeline, '_archive_input_image'), \
             patch.object(pipeline, '_finalize_analysis'):

            pipeline.process_image("dummy.png")

            mock_cc.assert_called_once()
            mock_ca.assert_called_once()

    @patch('src.pipeline.DatabaseManager')
    @patch('src.pipeline.SessionLocal')
    @patch('src.pipeline.load_image')
    def test_extract_metadata_delegation(self, mock_load, MockSession, MockDB, mock_args):
        # Verify that extracting metadata delegates to the utility
        mock_load.return_value = (np.zeros((100,100,3)), None)

        with patch('src.pipeline.ProjectManager'):
            pipeline = Pipeline(mock_args)

        with patch('src.pipeline.extract_metadata_from_filename') as mock_utils_meta, \
